import "server-only";
import type {Prisma,PrismaClient} from "@prisma/client";
import {BusinessError} from "@/lib/domain";

/** Partner codes are generated by the platform admin, never trusted from the URL alone. */
export const SALES_REFERRAL_PATTERN=/^ind-[0-9a-f]{12}$/;
type ControlDb=PrismaClient|Prisma.TransactionClient;
export type SalesPartner={id:string;code:string;name:string};

export async function resolveSalesPartner(db:ControlDb,referralCode:string|undefined):Promise<SalesPartner|null>{
 if(!referralCode)return null;
 if(!SALES_REFERRAL_PATTERN.test(referralCode))
   throw new BusinessError("Link de indicação inválido. Solicite um novo link ao parceiro.",400);
 const rows=await db.$queryRaw<Array<SalesPartner>>`
  SELECT id::text AS id,code,name FROM platform_sales_partners
  WHERE code=${referralCode} AND active=true LIMIT 1`;
 if(!rows[0])throw new BusinessError("Link de indicação não está ativo. Solicite um novo link ao parceiro.",400);
 return rows[0];
}

/** One attribution per tenant, inserted in the SAME transaction as registration.
 * Subsequent visits/links never steal attribution or restart the 7-day trial.
 */
export async function assignSalesReferral(tx:Prisma.TransactionClient,tenantId:string,partner:SalesPartner|null){
 if(!partner)return;
 await tx.$executeRaw`
  INSERT INTO platform_sales_referrals(tenant_id,partner_id)
  VALUES(${tenantId}::uuid,${partner.id}::uuid)`;
}
